#include <vector>

class Solution {
public:
    std::vector<int> minBitwiseArray(std::vector<int>& nums) {
        std::vector<int> ans;
        ans.reserve(nums.size());
        for (int p : nums) {
            if (p == 2) {
                ans.push_back(-1);
                continue;
            }
            for (int i = 0; i < 32; ++i) {
                if (!(p & (1 << i))) {
                    ans.push_back(p ^ (1 << (i - 1)));
                    break;
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] minBitwiseArray(List<Integer> nums) {
        int n = nums.size();
        int[] ans = new int[n];
        for (int j = 0; j < n; j++) {
            int p = nums.get(j);
            if (p == 2) {
                ans[j] = -1;
                continue;
            }
            for (int i = 0; i < 32; i++) {
                if ((p & (1 << i)) == 0) {
                    ans[j] = p ^ (1 << (i - 1));
                    break;
                }
            }
        }
        return ans;
    }
}

var minBitwiseArray = function(nums) {
    const ans = [];
    for (const p of nums) {
        if (p === 2) {
            ans.push(-1);
            continue;
        }
        for (let i = 0; i < 32; i++) {
            if (!(p & (1 << i))) {
                ans.push(p ^ (1 << (i - 1)));
                break;
            }
        }
    }
    return ans;
};
